// frontend/src/App.js
import React, { useState } from "react";
import StockItemForm from "./components/StockItemForm";
import StockItemList from "./components/StockItemList";
import SettingsForm from "./components/SettingsForm";
import SalesHistory from "./components/SalesHistory";
import FinancialDashboard from "./components/FinancialDashboard"; // 1. Importar
import api from "./api";

function App() {
  const [refreshKey, setRefreshKey] = useState(0);

  const [globalSettings, setGlobalSettings] = useState({
    iof_percent: "3.5",
    taxa_dolar: "5.30",
    shipping_method: "Air"
  });

  const handleDataChanged = () => {
    setRefreshKey((prevKey) => prevKey + 1);
  };

  return (
    <div className="App">
      <h1>Gerenciador de Compra e Venda de Acessórios Musicais</h1>

      {/* 2. Adicionar o Painel Financeiro */}
      {/* A 'key' garante que ele recarregue quando um item é vendido ou comprado */}
      <FinancialDashboard
        api={api}
        key={refreshKey - 1} // Chave diferente para garantir recarga
      />

      <SettingsForm
        settings={globalSettings}
        onSettingsChange={setGlobalSettings}
      />

      <StockItemForm
        api={api}
        onItemAdded={handleDataChanged}
        globalSettings={globalSettings}
      />

      <StockItemList
        api={api}
        key={refreshKey}
        onDataChanged={handleDataChanged}
      />

      <SalesHistory
        api={api}
        key={refreshKey + 1}
      />
    </div>
  );
}

export default App;
